/// 水平补偿波形:输入相位 `phase`(弧度),输出 [-1, 1]。
fn recoil_horizontal_wave(wave: HorizontalWave, phase: f32) -> f32 {
    match wave {
        HorizontalWave::Sine => phase.sin(),
        HorizontalWave::Triangle => {
            // 三角波:幅值线性往返。相位按 2π 归一化后落到 [-1,1]。
            let t = (phase / std::f32::consts::TAU).rem_euclid(1.0); // [0,1)
            if t < 0.25 { 4.0 * t } else if t < 0.75 { 2.0 - 4.0 * t } else { 4.0 * t - 4.0 }
        }
    }
}
