        let mut now = Instant::now();
        let mut peak: f32 = 0.0;
        let mut trough: f32 = 0.0;
        for _ in 0..200 {
            st.recoil_last = Some(now - step);
            now += step;
            recoil_tick(&ctl, &m, &aim, &mut st, &held, now);
            assert!(st.ox.abs() <= AMP + 1e-3, "水平补偿必须有界:{:?}", st.ox);
